  ADJETIVO = 'Adjetivo',
  VERBO = 'Verbo',
  ADVERBIO = 'Adverbio',
  PRONOMBRE = 'Pronombre',
  PREPOSICION = 'Preposición',
  CONJUNCION = 'Conjunción',
  DETERMINANTE = 'Determinante'
}

export type LevelGroup = 'Tutorial' | 'Literatura en español' | 'Literatura universal' | 'Tus Niveles';

export interface WordData {
  text: string;
  category: WordClass;
  id: string;
}

export interface Level {
  id: number;
  title: string;
  text: string;
  words: WordData[];
  timeLimit: number;
  targetCategory?: WordClass;
  categoryGroup?: LevelGroup;
}

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: string;
  unlocked: boolean;
  unlockedAt?: number;
  progress?: number;
  goal?: number;
}

export interface LeaderboardEntry {
  id?: string;
  name: string;
  score: number;
  created_at?: string;
}

export interface GameState {
  score: number;
  lives: number;
  time: number;
  levelIndex: number;
