  isGameOver: boolean;
  targetCategory: WordClass | null;
  mode: 'PRACTICE' | 'CHALLENGE_RANDOM' | 'CHALLENGE_PROGRESSIVE' | null;
  challengeStep: number; // Para el modo progresivo
