              <div className={`p-6 lg:p-10 rounded-[2rem] lg:rounded-[3rem] border-4 lg:border-8 flex flex-col transition-all ${missedWords.length > 0 ? (showKonamiEffect ? 'bg-indigo-950/20 border-indigo-900' : 'bg-indigo-50 border-indigo-100') : 'bg-emerald-50 border-emerald-100'}`}>
                <h3 className="text-sm lg:text-2xl font-black text-indigo-400 uppercase tracking-widest mb-4">
                  {missedWords.length > 0 ? 'PALABRAS QUE TE FALTARON' : '¡ERES UN MAESTRO!'}
